}
.kpi-value.green {
  color: var(--color-secondary);
}
.kpi-value.warning {
  color: var(--color-warning);
}
.kpi-value.danger {
  color: var(--color-danger);
}

@media (max-width: 768px) {
  .kpi-grid {
    grid-template-columns: repeat(2, 1fr);
    gap: 12px;
  }
